CREATE TABLE `articles` (
	`id` text PRIMARY KEY NOT NULL,
	`display_order` integer NOT NULL,
	`category` text NOT NULL,
	`title` text NOT NULL,
	`summary` text NOT NULL,
	`body` text NOT NULL,
	`image` text NOT NULL,
	`source` text NOT NULL,
	`published_at` text NOT NULL
);

INSERT INTO `articles` (`id`, `display_order`, `category`, `title`, `summary`, `body`, `image`, `source`, `published_at`) VALUES
  ('energy-2035', 1, '環境・エネルギー', '再生可能エネルギー、2035年までに電源構成の50%へ——新目標案を発表', '政府の有識者会議は、再生可能エネルギーの比率を大幅に引き上げる新たな目標案を公表しました。地域との合意形成や送電網整備が焦点です。', '["政府のエネルギー政策を検討する有識者会議は21日、2035年の電源構成に占める再生可能エネルギーの割合を50%程度まで引き上げる目標案を示しました。太陽光・風力の導入加速に加え、蓄電池と送電網への投資を一体で進める方針です。","一方、発電設備の立地をめぐっては、景観や自然環境への影響を懸念する声もあります。案では、自治体や住民が計画の初期段階から参加する仕組みを設け、地域への利益還元を事業者に求めるとしています。","今後は電気料金への影響や、天候に左右される電源を安定して運用するための費用負担が論点になります。政府は秋までに意見公募を行い、年内の計画決定を目指します。"]', 'https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=1200&q=85', 'civic-compass NEWS', '2時間前'),
  ('childcare', 2, '子育て・教育', '給食費の無償化、全国で段階導入へ　自治体間の格差解消を目指す', '公立小中学校の給食費を段階的に無償化する方針がまとまりました。財源の分担方法が今後の論点です。', '["公立小中学校の給食費について、国が費用の一部を負担し、全国で段階的に無償化する方針案が示されました。","先行して無償化している自治体との公平性や、食材価格が上昇する中で給食の質をどう確保するかが課題になります。"]', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=900&q=85', 'みらい通信', '4時間前'),
  ('mobility', 3, '地域・交通', '地方の移動を支える「日本版ライドシェア」、対象地域を拡大へ', '交通空白地帯への対応として、地域主体の移動サービスを拡大する案が検討されています。', '["公共交通の担い手不足が深刻な地域を対象に、日本版ライドシェアの運行エリアと時間帯を広げる案が公表されました。","安全管理と運転手の待遇、既存のタクシー事業との共存が主要な論点です。"]', 'https://images.unsplash.com/photo-1554797589-7241bb691973?auto=format&fit=crop&w=900&q=85', 'LOCAL POLICY', '6時間前'),
  ('workweek', 4, '働き方・経済', '選択的週休3日制を導入する企業、2年で倍増　生産性への効果は', '柔軟な働き方を導入する企業が増える一方、業種による導入格差も明らかになっています。', '["選択的週休3日制を導入した企業が、2年前と比べて約2倍になったことが民間調査で分かりました。","人材採用での効果が報告される一方、現場業務のある職種では人員確保が壁になっています。"]', 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=900&q=85', 'ECONOMY NOW', '昨日'),
  ('disaster', 5, '防災・自治体', '避難所の環境基準を初めて全国統一へ　プライバシー確保も明記', '災害時の避難所について、居住スペースや衛生設備の最低基準を国が示しました。', '["国は避難所の生活環境を改善するため、1人あたりの居住面積やトイレの設置数に関する共通基準案をまとめました。","自治体の財政負担をどう支えるか、平時から必要な備蓄をどう確保するかが検討されます。"]', 'https://images.unsplash.com/photo-1547683905-f686c993aae5?auto=format&fit=crop&w=900&q=85', '防災ジャーナル', '昨日'),
  ('digital', 6, 'デジタル行政', '行政手続きのオンライン化率9割へ　「書かない窓口」も拡大', '国と自治体の申請データを連携し、同じ情報を繰り返し記入する負担を減らす計画です。', '["行政手続きのオンライン完結率を高め、窓口でも申請書を書かずに済む仕組みを全国へ広げる工程表が示されました。","利便性向上とともに、高齢者などデジタル機器に不慣れな人への支援が求められます。"]', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=900&q=85', 'CIVIC TECH', '2日前'),
  ('housing', 7, '住宅・暮らし', '空き家を子育て世帯向け住宅へ　改修支援の新制度を検討', '増加する空き家と若年世帯の住宅負担を同時に解決する政策案が浮上しました。', '["自治体が認定した空き家を改修し、子育て世帯へ低廉な家賃で提供する新制度が検討されています。","所有者不明物件の扱いや、改修後の管理主体をどうするかが課題です。"]', 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=900&q=85', 'くらし政策部', '2日前'),
  ('care', 8, '医療・福祉', '在宅介護を支える家族への現金給付、モデル事業を5都市で開始', '介護離職を防ぐため、家族介護者への給付と相談支援を組み合わせる実証が始まります。', '["在宅で家族を介護する人を対象に、月額給付と相談支援を組み合わせたモデル事業が始まります。","家族だけに負担を集中させない制度設計と、介護サービスの供給拡大も同時に必要だと指摘されています。"]', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=900&q=85', 'HEALTH POLICY', '3日前');
